function beep(f=500,d=.08){if(!audioOn)return;try{audioCtx??=new AudioContext();audioCtx.resume();const o=audioCtx.createOscillator(),v=audioCtx.createGain();o.frequency.value=f;o.type='sine';v.gain.setValueAtTime(.06,audioCtx.currentTime);v.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(v);v.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d);}catch{}}
function toast(s){$('toast').textContent=s;toastTime=3.5;$('toast').style.opacity=1;}
function persist(){state.worldHomes=homes.map(h=>[h.type,h.x,h.z]);state.takenPearls=pearls.map(p=>p.taken);try{localStorage.setItem('shellbound-v1',JSON.stringify(state))}catch{}}
function quests(){return [{text:'搬进一间新家',sub:'靠近贝壳，按 E 试住',done:state.swaps>0},{text:`吃海藻，长大一点 ${Math.min(state.food,5)}/5`,sub:'绿色海藻会恢复饱腹与活力',done:state.food>=5},{text:`收集海里的珍珠 ${Math.min(state.totalPearls,6)}/6`,sub:'沿着海岸寻找闪光',done:state.totalPearls>=6},{text:'拜访薄荷壳邻居',sub:'椰林中的阿藻有一份礼物',done:state.friend},{text:'找到黄金鹦鹉螺',sub:'成年后，带 6 颗珍珠前往北岸',done:state.won}];}
function hud(){const t=types[state.shell];$('shellName').textContent=t.name;$('shellStats').textContent=`防御 ${t.def} · 速度 ${t.speed>1.1?'快':t.speed<1?'慢':'中'} · 容量 ${t.cap}`;$('level').textContent=['','幼年蟹','少年蟹','成年蟹','大个子'][state.size];$('health').style.width=state.health+'%';$('hunger').style.width=state.hunger+'%';$('healthNum').textContent=Math.ceil(state.health);$('hungerNum').textContent=Math.ceil(state.hunger);$('growth').textContent=`体型 ${state.size} · 成长 ${state.food%5} / 5`;$('pearls').textContent=`◈ ${state.pearls} 珍珠`;$('found').textContent=state.discovered.length+'/6';$('quests').innerHTML=quests().map(q=>`<div class="task ${q.done?'done':''}"><span class="check">${q.done?'✓':''}</span><div>${q.text}<small>${q.sub}</small></div></div>`).join('');$('day').textContent=`第 ${1+Math.floor(state.time/180)} 天`;}
function interact(){if(paused||!near)return;const n=near;if(n.kind==='shell'){const t=types[n.type];if(n.type===state.shell){toast('这和你现在的家一样，继续找找吧。');return;}if(t.cap<state.size){toast('这只壳太小了，已经装不下你。');return;}if(n.type===5&&state.size<3){toast('先吃海藻，成长到体型 3 再来试试。');return;}if(state.pearls<(t.cost||0)){toast(`还需要 ${(t.cost||0)-state.pearls} 颗珍珠。`);return;}const old=state.shell;state.pearls-=t.cost||0;state.shell=n.type;state.swaps++;if(!state.discovered.includes(n.type))state.discovered.push(n.type);scene.remove(n.g);n.type=old;n.g=shellModel(old,1.1);n.g.position.set(n.x,.2,n.z);scene.add(n.g);updateShell();state.health=Math.min(100,state.health+15);toast(`搬家成功！${t.name}，请多关照。`);beep(780,.2);if(state.shell===5&&!state.won){state.won=true;showModal('终于，找到理想的家。','<p>从一只漂流小螺，到闪闪发光的黄金鹦鹉螺。<br>这座海岛记住了你的每一段小脚印。</p><p>你可以继续收集全部六种贝壳、探索海岸，享受自己的海岛生活。</p>','继续海岛生活');}}else if(n.kind==='friend'){if(!state.friend){state.friend=true;state.pearls+=2;state.totalPearls+=2;toast('阿藻：送你 2 颗珍珠！北岸石门下藏着黄金壳。');beep(600,.2);}else toast('阿藻：涨潮时去椰林躲躲，按空格就能避开海鸥。');}hud();persist();}
function showModal(title,html,button='返回海岛'){paused=true;keys[' ']=false;$('modalTitle').innerHTML=title;$('modalBody').innerHTML=html;$('start').textContent=button;$('modal').classList.remove('hidden');}
function start(){active=true;paused=false;$('modal').classList.add('hidden');$('pause').textContent='Ⅱ';beep(450,.12);}
$('start').onclick=start;$('action').onclick=interact;$('touchE').onclick=interact;
$('pause').onclick=()=>{if(paused){start();return;}showModal('海风等你一会儿。','<p>旅途已自动保存在这台设备。<br>休息一下，再出发。</p>','继续探索');$('pause').textContent='▶';persist();};
$('help').onclick=()=>showModal('小蟹的生存手册','<p><b>WASD / 方向键</b> 移动，<b>Shift</b> 疾行，消耗更多饱腹。<br><b>E</b> 换壳或与邻居对话，靠近海藻和珍珠自动收集。<br><b>空格</b> 缩进壳里防御海鸥，缩壳时不能移动。<br><b>Q</b> 发出声呐，标记附近的壳和珍珠（冷却 8 秒）。</p><p>每吃 5 株海藻长大一级，最高体型 4。壳太小时速度会降低。容量不小于体型才能换入；稀有壳需要珍珠。<br>涨潮会淹没外侧浅滩，往岛中央走。生命耗尽会回到出生点，保留贝壳和成长、损失 1 颗珍珠。<br>触屏使用方向键及互动、缩壳按钮。</p>');
$('collection').onclick=()=>showModal('装得下梦想的家',types.map((t,i)=>`<div class="catalog-item"><b>${state.discovered.includes(i)?'✓':'○'} ${t.name}${state.shell===i?' · 正在使用':''}</b><p>${t.desc}</p><span>容量 ${t.cap} · 防御 ${t.def} · 速度 ${t.speed}×${t.cost?' · '+t.cost+' 珍珠':''}</span></div>`).join(''));
$('sound').onclick=()=>{audioOn=!audioOn;$('sound').style.background=audioOn?'#e8c46b':'#fffbeddb';$('sound').title=audioOn?'关闭声音':'开启声音';$('sound').setAttribute('aria-label',$('sound').title);beep();};
function sonar(){if(paused)return;if(scan>0){toast(`声呐恢复中 · ${Math.ceil(scan)} 秒`);return;}scan=8;toast('声呐已标记附近的贝壳与珍珠。');beep(950,.3);}
window.addEventListener('keydown',e=>{if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();const k=e.key.toLowerCase();keys[k]=true;if(e.repeat)return;if(k==='e')interact();if(k==='q')sonar();if(k==='escape')$('pause').click();});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);if(active&&!paused)$('pause').click();});
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true;};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false;}
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();
const map=$('minimap').getContext('2d');function minimap(){map.clearRect(0,0,180,140);map.fillStyle='#9ccbc0';map.beginPath();map.ellipse(90,70,80,59,-.1,0,7);map.fill();map.fillStyle='#ded6a8';map.beginPath();map.ellipse(90,70,70,50,-.1,0,7);map.fill();map.fillStyle='#a2b982';map.beginPath();map.ellipse(81,60,43,28,-.3,0,7);map.fill();const dot=(x,z,c,r=3)=>{map.fillStyle=c;map.beginPath();map.arc(90+x*2.5,70+z*2.5,r,0,7);map.fill();};for(const h of homes)dot(h.x,h.z,'#9e72a8');for(const p of pearls)if(!p.taken)dot(p.x,p.z,'#c1a35c',2);dot(npc.x,npc.z,'#4b8570',3);dot(state.x,state.z,'#fff8de',5);dot(state.x,state.z,'#e46947',3);map.fillStyle='#587f75';map.font='10px sans-serif';map.fillText('N',87,11);}
function takeFood(f){f.respawn=45;f.g.visible=false;state.food++;state.hunger=Math.min(100,state.hunger+23);state.health=Math.min(100,state.health+8);const size=Math.min(4,1+Math.floor(state.food/5));if(size>state.size){state.size=size;updateShell();toast(`长大啦！现在体型 ${size}${types[state.shell].cap<size?'，该找一只更大的壳了。':'，继续探索吧！'}`);}else toast('美味海藻 · 饱腹 +23 · 活力 +8');beep(650,.08);}
const clock=new THREE.Clock();let visualTime=0,hudTimer=0;function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.05);visualTime+=dt;const t=visualTime;const tide=(Math.sin(state.time/27-1.5)+1)/2;const high=tide>.72;
if(active&&!paused){const previousDay=Math.floor(state.time/180);state.time+=dt;if(Math.floor(state.time/180)>previousDay){pearls.forEach(p=>{p.taken=false;p.g.visible=true;});toast('新的一天，海浪带来了新的珍珠。');}state.hunger=Math.max(0,state.hunger-dt*(keys.shift?.7:.19));if(state.hunger===0)state.health-=dt*2;invuln=Math.max(0,invuln-dt);scan=Math.max(0,scan-dt);const hiding=!!keys[' '];let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dz=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);let moving=(dx||dz)&&!hiding;
if(moving){const len=Math.hypot(dx,dz);dx/=len;dz/=len;const vx=(dx+dz)*.707,vz=(dz-dx)*.707;let speed=types[state.shell].speed*3.3*(keys.shift&&state.hunger>10?1.65:1)*(types[state.shell].cap<state.size?.55:1);let nx=state.x+vx*dt*speed,nz=state.z+vz*dt*speed;const edge=Math.sqrt(nx*nx/625+nz*nz/361);if(edge>1){nx/=edge;nz/=edge;}for(const o of obstacles){let d=Math.hypot(nx-o.x,nz-o.z);if(d<o.r+.48&&d>.001){nx=o.x+(nx-o.x)*(o.r+.48)/d;nz=o.z+(nz-o.z)*(o.r+.48)/d;}}state.x=nx;state.z=nz;crab.rotation.y=Math.atan2(-vx,-vz);}
body.position.y=hiding?-.17:(moving?Math.sin(t*18)*.055:Math.sin(t*2)*.015);body.scale.set(hiding?.8:1,hiding?.75:1,hiding?.8:1);legs.forEach((l,i)=>{l.rotation.y=moving?Math.sin(t*19+i*1.5)*.35:0;l.visible=!hiding;});
const edge=Math.sqrt(state.x*state.x/625+state.z*state.z/361);if(high&&edge>.8){state.health-=dt*3;state.x*=1-dt*.035;state.z*=1-dt*.035;}
for(const f of foods){if(f.respawn>0){f.respawn-=dt;if(f.respawn<=0)f.g.visible=true;}else if(Math.hypot(state.x-f.x,state.z-f.z)<.85)takeFood(f);}
for(const p of pearls){if(!p.taken&&Math.hypot(state.x-p.x,state.z-p.z)<1){p.taken=true;p.g.visible=false;state.pearls++;state.totalPearls++;toast('找到一颗海洋珍珠 ◈');beep(1100,.18);}}
near=null;let nd=2.35;for(const obj of [...homes,npc]){const d=Math.hypot(state.x-obj.x,state.z-obj.z);if(d<nd){near=obj;nd=d;}}
$('interact').classList.toggle('hidden',!near);if(near){if(near.kind==='shell'){const sh=types[near.type];$('nearTitle').textContent=sh.name;$('nearDesc').textContent=`容量 ${sh.cap} · 防御 ${sh.def} · 速度 ${sh.speed}×${sh.cost?' · '+sh.cost+' 珍珠':''}`;$('action').textContent='E · 换上新家';}else{$('nearTitle').textContent='阿藻 · 椰林的老朋友';$('nearDesc').textContent='“嘿，新来的！要听听海岛的秘密吗？”';$('action').textContent='E · 打个招呼';}}
let threat=false;for(const b of birds){const cycle=(state.time+b.phase*9)%26;const danger=cycle>20;const a=state.time*.14+b.phase;const target=new THREE.Vector3(danger?state.x+Math.sin(cycle*2)*2:Math.cos(a)*18,danger?3.1:8+Math.sin(a),danger?state.z+Math.cos(cycle*2)*2:Math.sin(a)*13);b.g.position.lerp(target,dt*2);b.g.rotation.y=-a;b.wings.forEach((w,i)=>w.rotation.x=Math.sin(t*5)*.28*(i?1:-1));if(danger){threat=true;if(cycle>24.5&&invuln<=0&&!hiding){state.health-=Math.max(5,22-types[state.shell].def*3);invuln=2;toast('海鸥俯冲！按住空格缩进壳里。');beep(150,.2);}}}
$('danger').style.display=threat||high&&edge>.8?'block':'none';$('danger').textContent=threat?(hiding?'✓ 缩壳中 · 安全躲避':'⚠ 海鸥盘旋 · 按住空格缩壳'):'⚠ 涨潮了 · 请向岛中央移动';
if(state.health<=0){state.health=100;state.hunger=75;state.x=0;state.z=5;state.pearls=Math.max(0,state.pearls-1);invuln=5;toast('被海浪送回了浅滩，丢失 1 颗珍珠。重新出发！');}
if(saveTime>5){persist();saveTime=0;}saveTime+=dt;
}
crab.position.set(state.x,.13,state.z);crab.visible=invuln<=0||Math.floor(t*10)%2===0;ring.position.set(state.x,.035,state.z);ring.scale.setScalar(scan>6?1+(8-scan)*5:1);ring.material.opacity=scan>6?.5*(scan-6)/2:.3;
for(const p of pearls){p.g.position.y=.45+Math.sin(t*2+p.x)*.16;p.g.rotation.y=t;p.g.scale.setScalar(scan>5?1.5:1);}for(const h of homes){h.g.position.y=.18+Math.sin(t*1.5+h.x)*.06;h.g.rotation.y+=dt*.1;}
for(const {m,a}of foam){m.position.set(Math.cos(a)*(29-tide*4),-.27+Math.sin(t*2+a)*.025,Math.sin(a)*(23-tide*3));m.scale.x=1+Math.sin(t+a)*.25;}
lagoon.scale.set(1-tide*.1,1,.79-tide*.08);$('tide').textContent=high?'≈ 涨潮 · 远离浅滩':tide<.3?'☀ 退潮 · 适合探索':'≈ 潮水正在变化';$('region').textContent=state.x>12?'珊瑚湾':state.z<-9?'北岸遗迹':state.x<-3&&state.z<3?'椰林':'浅滩';
const mobile=innerWidth<600;const target=new THREE.Vector3(state.x*.66,0,state.z*.66);const cp=new THREE.Vector3(target.x+(mobile?21:25),mobile?31:34,target.z+(mobile?27:32));camera.position.lerp(cp,active?.045:.02);camera.lookAt(target.x,0,target.z-1);if(!active&&camera.position.length()<5)camera.position.copy(cp);
if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0;}hudTimer+=dt;if(hudTimer>.2){hud();minimap();hudTimer=0;}renderer.render(scene,camera);}
hud();frame();window.addEventListener('pagehide',persist);
window.shellbound={getState:()=>({...state,paused}),interact,start,pause:()=>{if(!paused)$('pause').click();}};
